(()=>{
'use strict';
const V='20260901-roster-v1';
const ORG_PLAYER_STATS=`team-data/player-kills-by-team.json?v=${V}`;
const root=document.getElementById('team-page-root');
const state={team:null,slug:'',current:null,stats:null,stages:null,seasonData:null,historyData:null,orgStats:null,activeSeason:'s2',historyExpanded:false,titlesExpanded:false};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'');
const num=v=>Number(v)||0;
const format=v=>num(v).toLocaleString('pt-BR');
const decimal=(v,d=2)=>num(v).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
const slug=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
const aliases={loud:'loud-snickers',fluxo:'fluxo-w7m',afg:'afrogames',a7:'alpha7',sxgaming:'sx-tet',sxtet:'sx-tet',cptvox:'cpt-vox',influencerage:'influence-rage',rise:'rise-gaming',rush:'rush-gaming',solid:'team-solid'};
async function json(url){const response=await fetch(url,{cache:'default'});if(!response.ok)throw new Error('Falha ao carregar os dados');return response.json()}
function findTeam(teams,query){const key=norm(query),mapped=aliases[key];return teams.find(t=>norm(t.name)===key||norm(t.abbreviation)===key||slug(t.name)===query||slug(t.name)===mapped)||teams.find(t=>slug(t.name)===mapped)||null}
function role(p){const value=String(p?.currentRoster?.roleShort||p?.currentRoster?.role||p?.role||'').toUpperCase();return value==='GRAN'?'Granadeiro':value==='SUP'?'Suporte':value==='3'?'3º homem':value==='RUSH'?'Rush':value||'Jogador'}
function photo(p){return window.cffResolvePlayerPhoto?.(p?.name,p?.photo)||p?.photo||'silhueta.webp'}function teamLogo(name,current=''){return window.cffResolveTeamLogo?.(name,current)||current||'escudo.webp'}
function playerStats(p,stats){const candidates=[p.id,p.name,...(p.aliases||[])].map(norm);const hit=Object.entries(stats||{}).find(([key,value])=>candidates.includes(norm(key))||candidates.includes(norm(value?.name)));return hit?.[1]||p.s2||{}}
function currentTeamRow(stages,name){const rows=['classificatoria','segundaFase','final'].flatMap(key=>Array.isArray(stages?.[key]?.rows)?stages[key].rows:[]);return rows.find(row=>norm(row.team||row.equipe||row.name)===norm(name))||{}}
function isDeparted(p){const r=p?.currentRoster||{};return Boolean(r.left)||norm(r.rosterStatus)==='saiu'}function tags(p){const roster=p.currentRoster||{};if(isDeparted(p))return'<span class="cff-player-tag departed">Saiu</span>';return[(roster.captain?'<span class="cff-player-tag captain">Capitão</span>':''),(roster.rookie?'<span class="cff-player-tag rookie">Estreante</span>':''),(roster.highlight?'<span class="cff-player-tag">Destaque</span>':''),(!roster.starter?'<span class="cff-player-tag">Reserva</span>':'')].join('')}
function currentPlayerCard(p,stats,logo){const s=playerStats(p,stats),roster=p.currentRoster||{},avg=num(s.matches)?num(s.kills)/num(s.matches):0;return `<a class="cff-player-card${isDeparted(p)?' is-departed':(roster.starter===false?' is-reserve':'')}" href="jogador.html?id=${encodeURIComponent(p.id||p.name)}"><div class="cff-player-photo-wrap"><img class="cff-player-photo" loading="lazy" decoding="async" src="${esc(photo(p))}" alt="${esc(p.name)}" onerror="this.onerror=null;this.src='silhueta.webp'"><img class="cff-player-team-mini" src="${esc(logo)}" data-team-logo="${esc(state.team?.name||'')}" alt=""></div><div class="cff-player-info"><h3>${esc(p.name)}</h3><span class="cff-player-role">${esc(role(p))} • ${esc(roster.rosterStatus||'Elenco')}</span><span class="cff-player-realname">${esc(roster.fullName||'')}${roster.state?` • ${esc(roster.state)}`:''}</span><div class="cff-player-tags">${tags(p)}</div></div><div class="cff-player-stats"><div class="cff-player-stat"><small>Abates</small><strong>${format(s.kills)}</strong></div><div class="cff-player-stat"><small>Dano</small><strong>${format(s.damage)}</strong></div><div class="cff-player-stat"><small>Quedas</small><strong>${format(s.matches)}</strong></div><div class="cff-player-stat"><small>Média</small><strong>${decimal(avg)}</strong></div></div></a>`}
function seasonPlayerCard(p,logo){return `<a class="cff-player-card" href="jogador.html?id=${encodeURIComponent(p.id||p.name)}"><div class="cff-player-photo-wrap"><img class="cff-player-photo" loading="lazy" decoding="async" src="${esc(p.photo||'silhueta.webp')}" alt="${esc(p.name)}" onerror="this.onerror=null;this.src='silhueta.webp'"><img class="cff-player-team-mini" src="${esc(logo)}" data-team-logo="${esc(state.team?.name||'')}" alt=""></div><div class="cff-player-info"><h3>${esc(p.name)}</h3><span class="cff-player-role">${esc(role(p))}</span></div><div class="cff-player-stats"><div class="cff-player-stat"><small>Abates</small><strong>${format(p.kills)}</strong></div><div class="cff-player-stat"><small>Dano</small><strong>${format(p.damage)}</strong></div><div class="cff-player-stat"><small>Quedas</small><strong>${format(p.matches)}</strong></div><div class="cff-player-stat"><small>Média</small><strong>${decimal(p.avg)}</strong></div></div></a>`}
function statCards(values){return `<section class="cff-team-stats">${values.map(([label,value])=>`<div class="cff-team-stat"><small>${esc(label)}</small><strong>${esc(value)}</strong></div>`).join('')}</section>`}
function stageCards(stages){if(!Array.isArray(stages)||!stages.length)return'';return `<div class="cff-season-stage-grid">${stages.map(stage=>`<article class="cff-season-stage-card${stage.champion?' is-champion':''}"><div class="cff-season-stage-top"><strong>${esc(stage.label||stage.id||'Etapa')}</strong><span>${stage.position?`${format(stage.position)}º`:'—'}</span></div><div class="cff-season-stage-stats"><span><b>${format(stage.points)}</b><small>Pontos</small></span><span><b>${format(stage.kills)}</b><small>Abates</small></span><span><b>${format(stage.booyahs)}</b><small>Booyahs</small></span><span><b>${format(stage.matches)}</b><small>Quedas</small></span></div>${stage.status?`<div class="cff-season-status">${esc(stage.status)}</div>`:''}</article>`).join('')}</div>`}
function seasonHeader(title,subtitle){return `<div class="cff-team-section-head cff-season-head"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div></div>`}
function renderS2(){state.activeSeason='s2';setSeasonButtons();const players=Object.values(state.current?.players||{}).sort((a,b)=>Number(isDeparted(a))-Number(isDeparted(b))||Number(b.currentRoster?.starter)-Number(a.currentRoster?.starter)||Number(b.currentRoster?.captain)-Number(a.currentRoster?.captain)||String(a.name).localeCompare(String(b.name),'pt-BR'));const row=currentTeamRow(state.stages,state.team.name),totals=players.reduce((acc,p)=>{const s=playerStats(p,state.stats?.players);acc.kills+=num(s.kills);acc.damage+=num(s.damage);acc.matches=Math.max(acc.matches,num(s.matches));return acc},{kills:0,damage:0,matches:0});const logo=teamLogo(state.team.name,state.team.logo);document.getElementById('cff-season-panel').innerHTML=`${seasonHeader('WB 2026 S2','Temporada atual')}${statCards([['Pontos',format(row.points??row.pontos)],['Abates',format(row.kills??row.abates??totals.kills)],['Booyahs',format(row.booyahs??row.booyah)],['Quedas',format(row.matches??row.quedas??totals.matches)]])}<section class="cff-team-section cff-season-roster-section"><div class="cff-team-section-head"><div><h2>Elenco da WB 2026 S2</h2></div><span class="cff-team-badge">${players.filter(p=>!isDeparted(p)&&p.currentRoster?.starter!==false).length} titulares${players.some(isDeparted)?` • ${players.filter(isDeparted).length} saiu`:''}</span></div><div class="cff-team-roster">${players.map(p=>currentPlayerCard(p,state.stats?.players,logo)).join('')}</div></section>`}
async function ensureSeasonData(){if(state.seasonData)return state.seasonData;state.seasonData=await json(`team-data/seasons/${state.slug}.json?v=${V}`);return state.seasonData}
async function selectSeason(key){if(key==='s2'){renderS2();return}state.activeSeason=key;setSeasonButtons();const panel=document.getElementById('cff-season-panel');panel.innerHTML='<section class="cff-inline-loading"><span></span><strong>Carregando temporada...</strong></section>';try{const data=await ensureSeasonData(),season=data?.seasons?.[key];if(!season){panel.innerHTML=`${seasonHeader(key==='s1'?'WB 2026 S1':'EWC 2026','A equipe não disputou esta competição.')}<div class="cff-public-empty">Nenhum resultado registrado para esta equipe.</div>`;return}const stages=season.stages||[],last=stages[stages.length-1]||{},totals=stages.reduce((a,s)=>(a.points+=num(s.points),a.kills+=num(s.kills),a.booyahs+=num(s.booyahs),a.matches+=num(s.matches),a),{points:0,kills:0,booyahs:0,matches:0});const players=season.players||[],title=key==='s1'?'WB 2026 S1':'EWC 2026';panel.innerHTML=`${seasonHeader(title,last.status||'Desempenho da equipe')}${statCards([['Melhor posição',last.position?`${format(last.position)}º`:'—'],['Pontos',format(totals.points)],['Abates',format(totals.kills)],['Quedas',format(totals.matches)]])}${stageCards(stages)}<section class="cff-team-section cff-season-roster-section"><div class="cff-team-section-head"><div><h2>Jogadores na competição</h2></div><span class="cff-team-badge">${players.length} jogadores</span></div><div class="cff-team-roster">${players.length?players.map(p=>seasonPlayerCard(p,teamLogo(state.team.name,state.team.logo))).join(''):'<div class="cff-public-empty">Elenco da competição não encontrado.</div>'}</div></section>`}catch(error){panel.innerHTML='<div class="cff-public-empty">Não foi possível carregar os dados desta competição.</div>'}}
function setSeasonButtons(){document.querySelectorAll('[data-team-season]').forEach(button=>{const active=button.dataset.teamSeason===state.activeSeason;button.classList.toggle('is-active',active);button.setAttribute('aria-selected',active?'true':'false')})}
async function ensureHistoryData(){if(state.historyData)return state.historyData;state.historyData=await json(`team-data/history/${state.slug}.json?v=${V}`);return state.historyData}
async function ensureOrgStats(){if(state.orgStats)return state.orgStats;state.orgStats=await json(ORG_PLAYER_STATS).catch(()=>({teams:{}}));return state.orgStats}
function softPlayerKey(value){return norm(value).replace(/\d+$/,'')}
function organizationPlayerStat(p){const team=state.orgStats?.teams?.[state.slug],rows=team?.players||[],keys=[p?.id,p?.name].filter(Boolean).map(norm);let hit=rows.find(row=>[row.name,...(row.aliases||[])].some(name=>keys.includes(norm(name))));if(hit)return hit;const softKeys=keys.map(softPlayerKey).filter(Boolean),near=rows.filter(row=>[row.name,...(row.aliases||[])].some(name=>softKeys.includes(softPlayerKey(name))));return near.length===1?near[0]:null}
function historyCard(p){const editions=(p.editions||[]).slice(-3).join(' • '),tag=p.isCurrent?'ELENCO ATUAL':String(p.cargo||'').toUpperCase()==='COACH'?'EX-TREINADOR':'EX-JOGADOR',org=organizationPlayerStat(p),orgKills=org?`${format(org.kills)} K`:(p.hasProfile===false?'—':'VER'),content=`<img src="${esc(p.photo||'silhueta.webp')}" alt="${esc(p.name)}" loading="lazy" decoding="async" onerror="this.onerror=null;this.src='silhueta.webp'"><span><strong>${esc(p.name)}</strong><small>${tag}</small><em>${esc(editions||p.currentTeam||'Passagem registrada')}</em></span><b title="Abates feitos por esta organização">${orgKills}</b>`;return p.hasProfile===false?`<article class="cff-history-player${p.isCurrent?' is-current':''} is-static">${content}</article>`:`<a class="cff-history-player${p.isCurrent?' is-current':''}" href="jogador.html?id=${encodeURIComponent(p.id||p.name)}">${content}</a>`}
function renderHistory(data){const mount=document.getElementById('cff-team-history-mount'),players=data?.history?.players||[],limit=state.historyExpanded?players.length:12,shown=players.slice(0,limit),leader=state.orgStats?.teams?.[state.slug]?.leader;mount.innerHTML=`<div class="cff-team-section-head"><div><h2>Jogadores que já defenderam a equipe</h2></div><div class="cff-history-counts">${leader?`<span>Maior artilheiro: ${esc(leader.name)} · ${format(leader.kills)} K</span>`:''}<span>${format(data?.history?.currentCount)} atuais</span><span>${format(data?.history?.formerCount)} ex-jogadores</span></div></div><div class="cff-history-grid">${shown.length?shown.map(historyCard).join(''):'<div class="cff-public-empty">Nenhum histórico de jogadores cadastrado.</div>'}</div>${players.length>12?`<button type="button" class="cff-section-more" id="cff-history-toggle">${state.historyExpanded?'Mostrar menos':'Ver todos os jogadores'}</button>`:''}`;document.getElementById('cff-history-toggle')?.addEventListener('click',()=>{state.historyExpanded=!state.historyExpanded;renderHistory(data)})}
function titleCard(t){return `<article class="cff-title-card"><img src="${esc(t.logo||'trofeu.webp')}" alt="" loading="lazy" decoding="async" onerror="this.onerror=null;this.src='trofeu.webp'"><div><strong>${esc(t.type||'Campeão')}</strong><span>${esc(t.event||'Competição')}</span><small>${esc([t.date,t.tier].filter(Boolean).join(' • '))}</small></div></article>`}
function renderTitles(data){const mount=document.getElementById('cff-team-titles-mount'),titles=data?.titles||[],limit=state.titlesExpanded?titles.length:8,shown=titles.slice(0,limit);mount.innerHTML=`<div class="cff-team-section-head"><div><h2>Títulos coletivos</h2></div><span class="cff-team-badge">${titles.length} conquistas</span></div><div class="cff-title-grid">${shown.length?shown.map(titleCard).join(''):'<div class="cff-public-empty">Nenhum título coletivo cadastrado.</div>'}</div>${titles.length>8?`<button type="button" class="cff-section-more" id="cff-titles-toggle">${state.titlesExpanded?'Mostrar menos':'Ver todos os títulos'}</button>`:''}`;document.getElementById('cff-titles-toggle')?.addEventListener('click',()=>{state.titlesExpanded=!state.titlesExpanded;renderTitles(data)})}
function placeBR(value){return String(value||'—').replace(/1st/i,'1º').replace(/2nd/i,'2º').replace(/3rd/i,'3º').replace(/(\d+)th/i,'$1º')}
function renderResults(data){const mount=document.getElementById('cff-team-results-mount'),rows=(data?.results||[]).slice(0,8);mount.innerHTML=`<div class="cff-team-section-head"><div><h2>Resultados recentes</h2></div></div><div class="cff-results-list">${rows.length?rows.map(r=>`<article class="cff-result-row"><strong>${esc(r.torneio||'Competição')}</strong><span>${esc(r.data||'')}</span><b>${esc(placeBR(r.place))}</b><small>${esc(r.tier||'')}</small></article>`).join(''):'<div class="cff-public-empty">Nenhum resultado recente cadastrado.</div>'}</div>`}
async function loadHistorySections(){const section=document.getElementById('cff-team-history-section');if(!section||section.dataset.loaded==='1')return;section.dataset.loaded='1';try{const [data]=await Promise.all([ensureHistoryData(),ensureOrgStats()]);renderHistory(data);renderTitles(data);renderResults(data)}catch(error){document.getElementById('cff-team-history-mount').innerHTML='<div class="cff-public-empty">Histórico indisponível no momento.</div>';document.getElementById('cff-team-titles-mount').innerHTML='';document.getElementById('cff-team-results-mount').innerHTML=''}}
function observeHistory(){const section=document.getElementById('cff-team-history-section');if(!section)return;if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)){observer.disconnect();loadHistorySections()}},{rootMargin:'500px 0px'});observer.observe(section)}else setTimeout(loadHistorySections,500)}
function renderShell(team){const logo=teamLogo(team.name,team.logo);document.title=`${team.name} | Central Free Fire`;root.innerHTML=`<section class="cff-team-hero"><img class="cff-team-logo" src="${esc(logo)}" data-team-logo="${esc(team.name)}" alt="${esc(team.name)}"><div><span class="cff-team-kicker">EQUIPE DE FREE FIRE</span><h1>${esc(team.name)}</h1><p>${esc(team.abbreviation||team.name)} • Brasil</p></div><span class="cff-team-country">Brasil</span></section><nav class="cff-season-tabs" aria-label="Temporadas"><button type="button" data-team-season="s2" class="is-active" aria-selected="true">WB 2026 S2</button><button type="button" data-team-season="s1" aria-selected="false">WB 2026 S1</button><button type="button" data-team-season="ewc" aria-selected="false">EWC 2026</button></nav><div id="cff-season-panel"></div><section id="cff-team-history-section" class="cff-team-section cff-history-section"><div id="cff-team-history-mount"><section class="cff-inline-loading"><span></span><strong>Carregando histórico...</strong></section></div><div id="cff-team-titles-mount"></div><div id="cff-team-results-mount"></div></section>`;document.querySelectorAll('[data-team-season]').forEach(button=>button.addEventListener('click',()=>selectSeason(button.dataset.teamSeason)));renderS2();observeHistory()}
function fail(message){root.innerHTML=`<section class="cff-team-error"><div><h1>Equipe não encontrada</h1><p>${esc(message||'Não foi possível carregar este perfil.')}</p><a href="index.html#ffws-br-s2-equipes">Voltar para as equipes</a></div></section>`}
async function init(){try{const params=new URLSearchParams(location.search),query=params.get('time')||params.get('id')||'';const teamsData=await json(`ffws-br-2026-s2/teams.json?v=${V}`),team=findTeam(teamsData.teams||[],query);if(!team)throw new Error('O nome informado não pertence aos times da temporada atual.');state.team=team;state.slug=aliases[norm(team.name)]||slug(team.name);const [,,current,stats,stages]=await Promise.all([window.cffLoadPlayerPhotoMap?.().catch(()=>null),window.cffLoadTeamLogoMap?.().catch(()=>null),json(`player-data/s2/${state.slug}.json?v=${V}`),json(`ffws-br-2026-s2/player-stats.json?v=${V}`).catch(()=>({players:{}})),json(`ffws-br-2026-s2/stages.json?v=${V}`).catch(()=>({}))]);state.current=current;state.stats=stats;state.stages=stages;renderShell(team)}catch(error){fail(error.message)}}
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init,{once:true}):init();
})();
